//! Token handoff from the credential store to a child process (the SDK
//! runner) via ENVIRONMENT VARIABLE ONLY: never argv, never a file, never logs.
//!
//! The env var name comes from Anthropic's Claude Code authentication docs:
//! `CLAUDE_CODE_OAUTH_TOKEN` ("A long-lived OAuth token generated by
//! `claude setup-token`"). The Agent SDK runs the Claude Code binary, so it
//! inherits the child's environment. The docs state `ANTHROPIC_AUTH_TOKEN`,
//! `ANTHROPIC_API_KEY` and `apiKeyHelper` all OUTRANK it, so the child
//! environment is rebuilt from an allowlist (`env_clear`) to make sure an
//! ambient API key can never silently win.
//!
//! The real SDK is replaced here by a stub (this same binary re-executed with
//! `--sdk-stub <mode>`). Never `Debug`-print the `Command`: std includes env
//! values in its Debug output.

use crate::secret::Secret;
use sha2::{Digest, Sha256};
use std::ffi::OsString;
use std::io::{BufRead, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

pub const TOKEN_ENV: &str = "CLAUDE_CODE_OAUTH_TOKEN";

/// Variables the docs say outrank `CLAUDE_CODE_OAUTH_TOKEN` (or switch provider).
/// They are never forwarded because the child env is built from an allowlist.
pub const OUTRANKING_ENV: &[&str] = &[
    "ANTHROPIC_AUTH_TOKEN",
    "ANTHROPIC_API_KEY",
    "CLAUDE_CODE_USE_BEDROCK",
    "CLAUDE_CODE_USE_VERTEX",
    "CLAUDE_CODE_USE_FOUNDRY",
    "ANTHROPIC_PROFILE",
];

const INHERIT: &[&str] = &["PATH", "LANG", "LC_ALL"];

pub fn fingerprint(token: &str) -> String {
    let d = Sha256::digest(token.as_bytes());
    d.iter().take(4).map(|b| format!("{b:02x}")).collect()
}

fn contains(hay: &[u8], needle: &[u8]) -> bool {
    !needle.is_empty() && hay.windows(needle.len()).any(|w| w == needle)
}

/// Build the child command. Only the token env var, an allowlist, and a
/// caller-chosen HOME/TMPDIR/cwd are set. Token never touches argv.
pub fn build_command(program: &Path, args: &[OsString], token: &Secret, home: &Path, cwd: &Path) -> Command {
    let mut c = Command::new(program);
    c.args(args).env_clear();
    for k in INHERIT {
        if let Ok(v) = std::env::var(k) {
            c.env(k, v);
        }
    }
    c.env("HOME", home)
        .env("TMPDIR", home)
        .env(TOKEN_ENV, token.expose())
        .current_dir(cwd)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    c
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StubMode {
    /// Well-behaved: reads env, logs no secrets, writes no files.
    Clean,
    /// Negative controls: prove the detectors actually detect leaks.
    LeakStdout,
    LeakStderr,
    LeakFile,
    LeakArgv,
}

impl StubMode {
    pub fn as_arg(self) -> &'static str {
        match self {
            StubMode::Clean => "clean",
            StubMode::LeakStdout => "leak-stdout",
            StubMode::LeakStderr => "leak-stderr",
            StubMode::LeakFile => "leak-file",
            StubMode::LeakArgv => "leak-argv",
        }
    }
    pub fn from_arg(s: &str) -> Option<Self> {
        Some(match s {
            "clean" => StubMode::Clean,
            "leak-stdout" => StubMode::LeakStdout,
            "leak-stderr" => StubMode::LeakStderr,
            "leak-file" => StubMode::LeakFile,
            "leak-argv" => StubMode::LeakArgv,
            _ => return None,
        })
    }
}

/// Body of the stub "SDK runner". Reads the token from its environment only.
pub fn run_stub(mode: StubMode) -> i32 {
    let token = std::env::var(TOKEN_ENV).ok();
    let cmdline = std::fs::read("/proc/self/cmdline").unwrap_or_default();
    let self_argv_has_token = token.as_ref().is_some_and(|t| contains(&cmdline, t.as_bytes()));
    println!(
        "SDK-STUB ready pid={} token_env_present={} token_len={} fingerprint={} self_argv_has_token={}",
        std::process::id(),
        token.is_some(),
        token.as_ref().map_or(0, |t| t.len()),
        token.as_deref().map(fingerprint).unwrap_or_default(),
        self_argv_has_token,
    );
    eprintln!("SDK-STUB diagnostic: started, mode={} (secrets are never logged)", mode.as_arg());
    if let Some(t) = token.as_deref() {
        match mode {
            StubMode::LeakStdout => println!("DEBUG auth header would be: Bearer {t}"),
            StubMode::LeakStderr => eprintln!("DEBUG auth header would be: Bearer {t}"),
            StubMode::LeakFile => {
                let _ = std::fs::write("token-cache.txt", t);
            }
            StubMode::Clean | StubMode::LeakArgv => {}
        }
    }
    let _ = std::io::stdout().flush();
    // Stay alive so the parent can inspect /proc/<pid>/{cmdline,environ}.
    let mut line = String::new();
    let _ = std::io::stdin().lock().read_line(&mut line);
    0
}

#[derive(Debug)]
pub struct HandoffReport {
    pub child_pid: u32,
    /// /proc/<pid>/environ contains exactly `CLAUDE_CODE_OAUTH_TOKEN=<token>`.
    pub env_has_token: bool,
    pub env_keys: Vec<String>,
    pub outranking_env_present: Vec<String>,
    /// /proc/<pid>/cmdline (as seen from OUTSIDE the child) contains the token.
    pub argv_has_token: bool,
    pub stdout_has_token: bool,
    pub stderr_has_token: bool,
    /// Recursive scan of the child's private HOME/TMPDIR/cwd directory.
    pub disk_has_token: bool,
    pub stub_saw_token: bool,
    pub stub_fingerprint_matches: bool,
    pub stub_self_argv_has_token: bool,
    pub exit_ok: bool,
    /// The child's private HOME/TMPDIR/cwd (deleted before `run_handoff` returns).
    pub scratch: PathBuf,
}

impl HandoffReport {
    /// True only if the handoff behaved exactly as required.
    pub fn is_clean_handoff(&self) -> bool {
        self.env_has_token
            && self.stub_saw_token
            && self.stub_fingerprint_matches
            && self.outranking_env_present.is_empty()
            && !self.argv_has_token
            && !self.stub_self_argv_has_token
            && !self.stdout_has_token
            && !self.stderr_has_token
            && !self.disk_has_token
            && self.exit_ok
    }
}

fn dir_contains(dir: &Path, needle: &[u8]) -> std::io::Result<bool> {
    for e in std::fs::read_dir(dir)? {
        let e = e?;
        let p = e.path();
        let ft = e.file_type()?;
        if ft.is_dir() {
            if dir_contains(&p, needle)? {
                return Ok(true);
            }
        } else if ft.is_file() && contains(&std::fs::read(&p)?, needle) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn scratch_dir() -> Result<PathBuf, String> {
    let p = std::env::temp_dir().join(format!("spike03-handoff-{}", crate::pkce::random_hex(8)?));
    std::fs::create_dir(&p).map_err(|e| format!("scratch dir: {e}"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o700));
    }
    Ok(p)
}

/// Drain a pipe on a thread. `first_line` (if given) is signalled once the
/// first newline has been seen.
fn read_all<R: Read + Send + 'static>(
    mut r: R,
    first_line: Option<std::sync::mpsc::Sender<()>>,
) -> std::thread::JoinHandle<Vec<u8>> {
    std::thread::spawn(move || {
        let mut v = Vec::new();
        let mut buf = [0u8; 1024];
        let mut signalled = first_line.is_none();
        loop {
            match r.read(&mut buf) {
                Ok(0) | Err(_) => break,
                Ok(n) => {
                    v.extend_from_slice(&buf[..n]);
                    if !signalled && v.contains(&b'\n') {
                        signalled = true;
                        if let Some(tx) = &first_line {
                            let _ = tx.send(());
                        }
                    }
                }
            }
        }
        v
    })
}

/// Spawn `stub_exe --sdk-stub <mode>` with the token handed over via env and
/// inspect it from the outside while it is alive.
pub fn run_handoff(stub_exe: &Path, mode: StubMode, token: &Secret) -> Result<HandoffReport, String> {
    run_handoff_with(stub_exe, mode, token, &read_proc)
}

/// Reads `/proc/<pid>/<file>`. Injectable so tests can force the inspection to fail.
pub type ProcReader<'a> = &'a dyn Fn(u32, &str) -> std::io::Result<Vec<u8>>;

pub fn read_proc(pid: u32, file: &str) -> std::io::Result<Vec<u8>> {
    std::fs::read(format!("/proc/{pid}/{file}"))
}

/// Same as [`run_handoff`] with an injectable `/proc` reader.
pub fn run_handoff_with(stub_exe: &Path, mode: StubMode, token: &Secret, proc_reader: ProcReader) -> Result<HandoffReport, String> {
    let scratch = scratch_dir()?;
    let result = run_handoff_in(stub_exe, mode, token, &scratch, proc_reader);
    // Only after run_handoff_in has returned: its guard has already killed and
    // reaped the child, so no live process can be left holding the token.
    let _ = std::fs::remove_dir_all(&scratch);
    result
}

/// Owns the spawned stub and its pipe-reader threads. On drop (every early
/// return, including `?`) it kills and reaps the child, then joins the readers,
/// so no orphan holding the token in its environment can outlive the call.
struct ChildGuard {
    child: std::process::Child,
    readers: Vec<std::thread::JoinHandle<Vec<u8>>>,
    reaped: bool,
}

impl Drop for ChildGuard {
    fn drop(&mut self) {
        if !self.reaped {
            let _ = self.child.kill();
            let _ = self.child.wait();
        }
        // Pipes are closed once the child is gone, so the readers finish.
        for h in self.readers.drain(..) {
            let _ = h.join();
        }
    }
}

fn run_handoff_in(stub_exe: &Path, mode: StubMode, token: &Secret, scratch: &Path, proc_reader: ProcReader) -> Result<HandoffReport, String> {
    let mut args: Vec<OsString> = vec!["--sdk-stub".into(), mode.as_arg().into()];
    if mode == StubMode::LeakArgv {
        // Deliberately wrong: negative control for the argv detector.
        args.push(format!("--token={}", token.expose()).into());
    }
    let mut cmd = build_command(stub_exe, &args, token, scratch, scratch);
    let mut child = cmd.spawn().map_err(|e| format!("spawn stub: {e}"))?;
    let pid = child.id();
    // Take the pipes before anything can fail, then hand everything to the guard
    // so EVERY later `?` kills + reaps the child and joins the readers.
    let (child_out, child_err, child_in) = (child.stdout.take(), child.stderr.take(), child.stdin.take());
    let mut guard = ChildGuard { child, readers: Vec::new(), reaped: false };
    let (ready_tx, ready_rx) = std::sync::mpsc::channel();
    let child_out = child_out.ok_or("no stdout")?;
    let child_err = child_err.ok_or("no stderr")?;
    guard.readers.push(read_all(child_out, Some(ready_tx)));
    guard.readers.push(read_all(child_err, None));

    // Wait for the stub's "ready" line before touching /proc: right after
    // spawn() the kernel may not have populated the new mm's env/arg ranges yet
    // (observed: empty /proc/<pid>/environ). Once the stub has printed, exec is done.
    if ready_rx.recv_timeout(Duration::from_secs(10)).is_err() {
        return Err("stub never printed its ready line".into());
    }
    let cmdline = proc_reader(pid, "cmdline").map_err(|e| format!("read cmdline: {e}"))?;
    let environ = proc_reader(pid, "environ").map_err(|e| format!("read environ: {e}"))?;
    let want = format!("{TOKEN_ENV}={}", token.expose());
    let env_has_token = environ.split(|b| *b == 0).any(|kv| kv == want.as_bytes());
    let env_keys: Vec<String> = environ
        .split(|b| *b == 0)
        .filter(|kv| !kv.is_empty())
        .map(|kv| String::from_utf8_lossy(kv).split('=').next().unwrap_or("").to_string())
        .collect();
    let outranking_env_present = OUTRANKING_ENV
        .iter()
        .filter(|k| env_keys.iter().any(|e| e == *k))
        .map(|k| k.to_string())
        .collect();
    let argv_has_token = contains(&cmdline, token.expose().as_bytes());

    // Release the stub and wait (bounded).
    if let Some(mut stdin) = child_in {
        let _ = stdin.write_all(b"\n");
    }
    let deadline = Instant::now() + Duration::from_secs(10);
    let status = loop {
        match guard.child.try_wait().map_err(|e| e.to_string())? {
            Some(s) => {
                guard.reaped = true;
                break s;
            }
            None if Instant::now() >= deadline => return Err("stub did not exit in 10s".into()),
            None => std::thread::sleep(Duration::from_millis(10)),
        }
    };
    let mut readers = std::mem::take(&mut guard.readers).into_iter();
    let stdout = readers.next().ok_or("missing stdout reader")?.join().map_err(|_| "stdout reader panicked")?;
    let stderr = readers.next().ok_or("missing stderr reader")?.join().map_err(|_| "stderr reader panicked")?;
    let disk_has_token = dir_contains(scratch, token.expose().as_bytes()).map_err(|e| format!("disk scan: {e}"))?;

    let stdout_text = String::from_utf8_lossy(&stdout);
    let ready = stdout_text.lines().find(|l| l.starts_with("SDK-STUB ready")).unwrap_or("");
    let field = |name: &str| {
        ready
            .split_whitespace()
            .find_map(|kv| kv.strip_prefix(&format!("{name}=")))
            .unwrap_or("")
            .to_string()
    };
    Ok(HandoffReport {
        child_pid: pid,
        env_has_token,
        env_keys,
        outranking_env_present,
        argv_has_token,
        stdout_has_token: contains(&stdout, token.expose().as_bytes()),
        stderr_has_token: contains(&stderr, token.expose().as_bytes()),
        disk_has_token,
        stub_saw_token: field("token_env_present") == "true",
        stub_fingerprint_matches: field("fingerprint") == fingerprint(token.expose()),
        stub_self_argv_has_token: field("self_argv_has_token") == "true",
        exit_ok: status.success(),
        scratch: scratch.to_path_buf(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detector_helper_behaves() {
        assert!(contains(b"abc\0TOKEN=xyz\0", b"xyz"));
        assert!(!contains(b"abc", b"xyz"));
        assert!(!contains(b"abc", b""));
    }

    #[test]
    fn built_command_has_token_only_in_env() {
        let tok = Secret::new("SYNTH-ONLY-IN-ENV");
        let tmp = std::env::temp_dir();
        let c = build_command(Path::new("/bin/true"), &["--flag".into()], &tok, &tmp, &tmp);
        assert!(c.get_args().all(|a| !a.to_string_lossy().contains("SYNTH")));
        let envs: Vec<_> = c.get_envs().collect();
        assert!(envs
            .iter()
            .any(|(k, v)| *k == TOKEN_ENV && v.map(|v| v == "SYNTH-ONLY-IN-ENV").unwrap_or(false)));
        for bad in OUTRANKING_ENV {
            assert!(!envs.iter().any(|(k, _)| k == bad), "{bad} must not be set");
        }
    }

    #[test]
    fn stub_mode_roundtrip() {
        for m in [
            StubMode::Clean,
            StubMode::LeakStdout,
            StubMode::LeakStderr,
            StubMode::LeakFile,
            StubMode::LeakArgv,
        ] {
            assert_eq!(StubMode::from_arg(m.as_arg()), Some(m));
        }
        assert_eq!(StubMode::from_arg("nope"), None);
    }
}
